let listeners = [];

export async function initStore() {
  try {
    const tasks = await db.getAll('tasks') || [];
    const projects = await db.getAll('projects') || [];
    const files = await db.getAll('files') || [];
    const settings = await db.get('settings', 'app') || state.settings;
    state.tasks = tasks;
    state.projects = projects;
    state.files = files;
    state.settings = settings;
  } catch (err) {
    console.warn('Store init fallback to default state', err);
  }
}

export function getState() {
  return state;
}

export async function dispatch(action, payload) {
  const prevState = JSON.parse(JSON.stringify(state));
  switch (action) {
    case 'ADD_TASK':
      state.tasks.push(payload);
      await db.put('tasks', payload);
      emit('TASK_CREATED', payload);
      break;
    case 'UPDATE_TASK':
      state.tasks = state.tasks.map(t => t.id === payload.id ? payload : t);
      await db.put('tasks', payload);
      emit('TASK_UPDATED', payload);
      break;
    case 'DELETE_TASK':
      state.tasks = state.tasks.filter(t => t.id !== payload);
      await db.delete('tasks', payload);
      emit('TASK_DELETED', payload);
      break;
    case 'ADD_PROJECT':
      state.projects.push(payload);
      await db.put('projects', payload);
      emit('PROJECT_CREATED', payload);
      break;
    case 'UPDATE_SETTINGS':
      state.settings = { ...state.settings, ...payload };
      await db.put('settings', { id: 'app', ...state.settings });
      emit('SETTINGS_CHANGED', state.settings);
      break;
    case 'ADD_NOTIFICATION':
      state.notifications.unshift(payload);
      break;
    case 'CLEAR_NOTIFICATIONS':
      state.notifications = [];
      break;
    case 'OPEN_WINDOW':
      if (!state.windows.some(w => w.id === payload.id)) {
        state.windows.push({ ...payload, zIndex: state.windows.length + 1, minimized: false });
        emit('WINDOW_OPENED', payload);
      }
      break;
    case 'CLOSE_WINDOW':
      state.windows = state.windows.filter(w => w.id !== payload);
      emit('WINDOW_CLOSED', payload);
      break;
    case 'TOGGLE_LOCK':
      state.sessions.locked = !state.sessions.locked;
      break;
    default:
      console.warn('Unknown action:', action);
  }
  state.history.undoStack.push({ action, payload, prevState });
  state.history.redoStack = [];
  notifyListeners();
}

export function subscribe(listener) {
  listeners.push(listener);
  return () => {
    listeners = listeners.filter(l => l !== listener);
  };
}

function notifyListeners() {
  listeners.forEach(l => l(state));
}

export function createSelector(selectorFn) {
  return state => selectorFn(state);
}

const DB_NAME = 'OmegaDesktopDB';
const DB_VERSION = 1;
const STORES = ['tasks', 'projects', 'documents', 'spreadsheets', 'files', 'notifications', 'settings', 'activity', 'snapshots'];

let idb = null;
let useLocalStorage = false;

export async function initDatabase() {
  return new Promise((resolve) => {
    if (!window.indexedDB) {
      useLocalStorage = true;
      resolve(true);
      return;
    }
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onerror = () => {
      useLocalStorage = true;
      resolve(true);
    };
    request.onsuccess = event => {
      idb = event.target.result;
      resolve(true);
    };
    request.onupgradeneeded = event => {
      const dbInstance = event.target.result;
      STORES.forEach(storeName => {
        if (!dbInstance.objectStoreNames.contains(storeName)) {
          dbInstance.createObjectStore(storeName, { keyPath: 'id' });
        }
      });
    };
  });
}

export const db = {
  async get(storeName, id) {
    if (useLocalStorage) {
      const data = JSON.parse(localStorage.getItem(`${DB_NAME}_${storeName}`) || '{}');
      return data[id] || null;
    }
    return new Promise(resolve => {
      const tx = idb.transaction(storeName, 'readonly');
      const req = tx.objectStore(storeName).get(id);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => resolve(null);
    });
  },
  async getAll(storeName) {
    if (useLocalStorage) {
      const data = JSON.parse(localStorage.getItem(`${DB_NAME}_${storeName}`) || '{}');
      return Object.values(data);
    }
    return new Promise(resolve => {
      const tx = idb.transaction(storeName, 'readonly');
      const req = tx.objectStore(storeName).getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => resolve([]);
    });
  },
  async put(storeName, value) {
    if (!value.id) value.id = 'id_' + Math.random().toString(36).substr(2, 9);
    if (useLocalStorage) {
      const data = JSON.parse(localStorage.getItem(`${DB_NAME}_${storeName}`) || '{}');
      data[value.id] = value;
      localStorage.setItem(`${DB_NAME}_${storeName}`, JSON.stringify(data));
      return value;
    }
    return new Promise(resolve => {
      const tx = idb.transaction(storeName, 'readwrite');
      const req = tx.objectStore(storeName).put(value);
      req.onsuccess = () => resolve(value);
      req.onerror = () => resolve(null);
    });
  },
  async delete(storeName, id) {
    if (useLocalStorage) {
      const data = JSON.parse(localStorage.getItem(`${DB_NAME}_${storeName}`) || '{}');
      delete data[id];
      localStorage.setItem(`${DB_NAME}_${storeName}`, JSON.stringify(data));
      return true;
    }
    return new Promise(resolve => {
      const tx = idb.transaction(storeName, 'readwrite');
      const req = tx.objectStore(storeName).delete(id);
      req.onsuccess = () => resolve(true);
      req.onerror = () => resolve(false);
    });
  }
};

