}

export function validateTaskDependencies(tasks, taskId, dependencyId) {
  if (taskId === dependencyId) return false;
  let visited = new Set();
  let queue = [dependencyId];
  while (queue.length > 0) {
    let curr = queue.shift();
    if (curr === taskId) return false;
    if (visited.has(curr)) continue;
    visited.add(curr);
    let t = tasks.find(x => x.id === curr);
    if (t && t.dependencies) {
      queue.push(...t.dependencies);
    }
  }
  return true;
}

export function calculateProjectProgress(project, tasks) {
  const pTasks = tasks.filter(t => t.projectId === project.id);
  if (pTasks.length === 0) return 0;
  const completed = pTasks.filter(t => t.status === 'done').length;
  return Math.round((completed / pTasks.length) * 100);
}

export function getMonthDays(year, month) {
  const date = new Date(year, month, 1);
  const days = [];
  while (date.getMonth() === month) {
    days.push(new Date(date));
    date.setDate(date.getDate() + 1);
  }
  return days;
}

export function searchEntities(state, query) {
  const q = query.toLowerCase();
  const tasks = state.tasks.filter(t => t.title.toLowerCase().includes(q));
  const projects = state.projects.filter(p => p.name.toLowerCase().includes(q));
  return { tasks, projects };
}

export function undo(state) {
  if (state.history.undoStack.length === 0) return state;
  const item = state.history.undoStack.pop();
  state.history.redoStack.push(item);
  return item.prevState;
}

export function processSyncQueue(queue) {
  return queue.map(item => ({ ...item, synced: true }));
}

